// ============================================================
// DEDUPLICATE: Skip deals we've already processed
// Uses n8n static data (persisted in PostgreSQL on Railway)
// ============================================================

const results = $input.first().json.results || [];

if (results.length === 0) {
  return []; // No confirmed deals — workflow stops
}

const processed = $getWorkflowStaticData('global');
if (!processed.dealIds) {
  processed.dealIds = [];
}

const newDeals = [];

for (const deal of results) {
  if (!processed.dealIds.includes(deal.id)) {
    newDeals.push({ json: { dealId: deal.id, dealName: deal.properties.dealname } });
    processed.dealIds.push(deal.id);
  }
}

// Cap at 500 IDs to prevent unbounded growth
if (processed.dealIds.length > 500) {
  processed.dealIds = processed.dealIds.slice(-500);
}

return newDeals;

// Build the batch read payload from quote's line item associations
const quote = $input.first().json;
const lineItemAssociations = quote.associations?.line_items?.results || quote.associations?.['line items']?.results || [];

if (lineItemAssociations.length === 0) {
  throw new Error('No line items found on quote ' + (quote.id || 'unknown'));
}

const payload = {
  inputs: lineItemAssociations.map(l => ({ id: l.id })),
  properties: ['name', 'quantity', 'price', 'hs_sku', 'description', 'amount', 'hs_line_item_currency_code', 'discount', 'tax']
};

return { json: { batchPayload: payload } };

// ============================================================
// NORMALIZE: Combine deal + quote + line items + contact
// into a single clean object for downstream branches
// ============================================================

const deal = $('Get Deal Details').first().json;
const quote = $('Get Quote').first().json;
const lineItemsRaw = $('Get Line Items').first().json;
const contact = $('Get Contact').first().json;

const lineItems = (lineItemsRaw.results || []).map(li => ({
  name: li.properties.name || 'Item',
  description: li.properties.description || '',
  sku: li.properties.hs_sku || '',
  quantity: parseFloat(li.properties.quantity) || 1,
  unitPrice: parseFloat(li.properties.price) || 0,
  amount: parseFloat(li.properties.amount) || 0,
  discount: parseFloat(li.properties.discount) || 0,
  tax: parseFloat(li.properties.tax) || 0
}));

const cp = contact.properties || {};
const hasShippingAddress = !!(cp.hs_shipping_address && cp.hs_shipping_address.trim());

const billingAddress = {
  name: `${cp.firstname || ''} ${cp.lastname || ''}`.trim(),
  company: cp.company || '',
  street1: cp.address || '',
  city: cp.city || '',
  state: cp.state || '',
  postalCode: cp.zip || '',
  country: cp.country || 'US',
  phone: cp.phone || ''
};

const shippingAddress = hasShippingAddress ? {
  name: billingAddress.name,
  company: billingAddress.company,
  street1: cp.hs_shipping_address || '',
  city: cp.hs_shipping_city || '',
  state: cp.hs_shipping_state || '',
  postalCode: cp.hs_shipping_zip || '',
  country: cp.hs_shipping_country || 'US',
  phone: billingAddress.phone
} : { ...billingAddress };

const subtotal = lineItems.reduce((sum, li) => sum + li.amount, 0);

return {
  json: {
    // IDs for cross-referencing
    dealId: deal.id,
    dealName: deal.properties.dealname,
    quoteId: quote.id,
    quoteNumber: quote.properties.hs_quote_number || '',
    quoteTitle: quote.properties.hs_title || '',
    signStatus: quote.properties.hs_sign_status || '',
    esignDate: quote.properties.hs_esign_date || '',

    // Financial
    currency: quote.properties.hs_currency || 'USD',
    quoteAmount: parseFloat(quote.properties.hs_quote_amount) || 0,
    subtotal: subtotal,
    closeDate: deal.properties.closedate,

    // Customer
    customerEmail: cp.email || '',
    customerName: billingAddress.name,
    customerPhone: cp.phone || '',
    contactId: contact.id,
    billingAddress: billingAddress,
    shippingAddress: shippingAddress,
    hasShippingAddress: hasShippingAddress,

    // Line items
    lineItems: lineItems,
    itemCount: lineItems.length,
    itemSummary: lineItems.map(li => `${li.quantity}x ${li.name}`).join(', '),

    // ShipStation dedup key (deterministic)
    shipStationOrderKey: `hubspot-deal-${deal.id}`
  }
};

// ============================================================
// PARSE LAST MX NUMBER AND INCREMENT
// ============================================================

const lastInvoice = $input.first().json;
const invoices = lastInvoice.QueryResponse?.Invoice || [];

let nextNumber = 10001; // Starting number if no mx invoices exist

if (invoices.length > 0) {
  const lastDocNumber = invoices[0].DocNumber || '';
  const match = lastDocNumber.match(/^mx(\d+)$/i);
  if (match) {
    nextNumber = parseInt(match[1], 10) + 1;
  }
}

// Format: mx + zero-padded to at least 5 digits
const mxNumber = 'mx' + String(nextNumber).padStart(5, '0');

// Pass through all data from Normalize Data
const normalizeData = $('Normalize Data').first().json;

return {
  json: {
    ...normalizeData,
    mxNumber: mxNumber,
    mxRawNumber: nextNumber
  }
};

const customer = $json.QueryResponse.Customer[0];
return {
  json: {
    ...$('Generate Next mx Number').first().json,
    qboCustomerId: customer.Id,
    qboCustomerIsNew: false
  }
};

