// ============================================================
// BUILD QBO INVOICE WITH MX NUMBER
// Avalara handles sales tax — no TaxCodeRef or TxnTaxDetail
// ============================================================

const qboItemsResponse = $input.first().json;
const allQboItems = qboItemsResponse.QueryResponse?.Item || [];

// Get customer data from whichever branch executed
let prevData;
try {
  prevData = $('Use New Customer').first().json;
} catch (e) {
  prevData = $('Use Existing Customer').first().json;
}

// Build SKU → QBO Item ID lookup
const skuToItemId = {};
allQboItems.forEach(item => {
  if (item.Sku) skuToItemId[item.Sku.trim().toUpperCase()] = item.Id;
  if (item.Name) skuToItemId[item.Name.trim().toUpperCase()];
});

const invoiceLines = prevData.lineItems.map(li => {
  const skuKey = (li.sku || li.name || '').trim().toUpperCase();
  const qboItemId = skuToItemId[skuKey];

  if (!qboItemId) {
    console.log(`WARNING: No QBO item found for SKU "${li.sku}" / Name "${li.name}"`);
  }

  const line = {
    DetailType: 'SalesItemLineDetail',
    Amount: li.quantity * li.unitPrice,
    Description: li.description || li.name,
    SalesItemLineDetail: {
      Qty: li.quantity,
      UnitPrice: li.unitPrice
    }
  };

  if (qboItemId) {
    line.SalesItemLineDetail.ItemRef = { value: qboItemId.toString() };
  }

  return line;
});

const invoicePayload = {
  CustomerRef: { value: prevData.qboCustomerId.toString() },
  DocNumber: prevData.mxNumber,
  TxnDate: new Date().toISOString().split('T')[0],
  BillEmail: { Address: prevData.customerEmail },
  ShipAddr: {
    Line1: prevData.shippingAddress.street1,
    City: prevData.shippingAddress.city,
    CountrySubDivisionCode: prevData.shippingAddress.state,
    PostalCode: prevData.shippingAddress.postalCode,
    Country: prevData.shippingAddress.country
  },
  Line: invoiceLines,
  PrivateNote: `HubSpot Deal: ${prevData.dealName} | Quote: ${prevData.quoteNumber} | Deal ID: ${prevData.dealId}`
};

return {
  json: {
    ...prevData,
    invoicePayload: invoicePayload
  }
};

